export function isHiveWord(w: string): boolean {
  return WORDS.has(w.toUpperCase());
}

/** Every listed word (4+ letters) built only from the hive letters and using the center. */
export function hiveWordsFor(letters: string[], center: string): string[] {
  const allowed = new Set([...letters, center].map((l) => l.toUpperCase()));
  const c = center.toUpperCase();
  const out: string[] = [];
  for (const w of WORDS) {
    if (w.length < 4 || !w.includes(c)) continue;
    let ok = true;
    for (const ch of w) if (!allowed.has(ch)) { ok = false; break; }
    if (ok) out.push(w);
  }
  return out.sort((a, b) => b.length - a.length || a.localeCompare(b));
}
